{
  "sop_id": "SOP-021",
  "title": "Employee Document Verification",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign to Executor",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check checklist completeness and document legibility",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify identity and address proofs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Send education and employment confirmations to issuers or BGV agency",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Cross-check names, dates, grade, and salary against offer letter and HRMS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Record verification status and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for credential confirmations (DependencyWait)",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "A1",
      "name": "Incharge approves or rejects with reason code",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "On rejection, correct and resubmit",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if discrepancy"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Issuer / BGV agency",
      "item": "Credential confirmations",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.9
}
